// Retexia — Plan (plan.retexia.com). EDIT only the values marked EDIT.
// The OpenRouter key lives in the n8n credential of the three "OpenRouter" nodes.
const CONFIG = {
  retexiaKey: 'EDIT: the same value as PLAN_N8N_KEY in the Retexia panels (Vercel)',
  evolutionUrl: 'EDIT: https://your-evolution-server',
  evolutionKey: 'EDIT: the Evolution API key',
  evolutionInstance: 'EDIT: the instance name, e.g. retexia-plan',
};

// Only Retexia may call this webhook (header X-Retexia-Key).
const input = $input.first().json;
const given = String((input.headers || {})['x-retexia-key'] || '');
if (CONFIG.retexiaKey.startsWith('EDIT') || given !== CONFIG.retexiaKey) throw new Error('Unauthorized: wrong or missing X-Retexia-Key (set retexiaKey in Config).');
const body = input.body || {};
const ACTIONS = ['coach', 'morning', 'weekly', 'whatsapp'];
let action = ACTIONS.includes(body.action) ? body.action : '';
if (!action) throw new Error('Unknown action: ' + body.action);

// WhatsApp jobs need the Evolution line.
let notReady = '';
if (action === 'morning' || action === 'whatsapp') {
  const missing = ['evolutionUrl', 'evolutionKey', 'evolutionInstance'].filter((k) => !CONFIG[k] || String(CONFIG[k]).startsWith('EDIT'));
  if (missing.length) { notReady = 'Retexia Plan WhatsApp is not set up in n8n: fill in ' + missing.join(', ') + ' in Config.'; action = 'not_ready'; }
  else if (String(body.number || '').replace(/\D/g, '').length < 9) { notReady = 'No WhatsApp number.'; action = 'not_ready'; }
}
return [{ json: { ...CONFIG, action, notReady, context: body.context || {}, number: String(body.number || ''), text: String(body.text || '').slice(0, 4000) } }];

const r = $input.first().json || {};
const reply = String(r.text || r.output || r.response || '').trim();
return [{ json: { ok: !!reply, reply: reply || '', error: reply ? undefined : String((r.error && (r.error.message || r.error)) || 'The AI did not answer.').slice(0, 200) } }];

const c = $input.first().json.context || {};
const prompt = [
  'Write a WhatsApp good-morning message for ' + (c.name || 'the user') + ' from Retexia Plan, in ' + (c.language || 'English') + '.',
  'Max 600 characters. A one-line greeting; today\'s tasks as a short list with "•"; the streak (celebrate it, or encourage starting one if it is 0); one line about the goal that needs the most attention (or the best one) with a tiny tip; end with: ' + (c.link || ''),
  'Friendly and energetic, a few emoji. Use ONLY these facts, never invent numbers:',
  JSON.stringify({ today: c.today, tasks_today: c.tasks_today, streak_days: c.streak_days, best_streak: c.best_streak, goals: c.goals }, null, 1),
  'Reply with only the message.',
].join('\n');
return [{ json: { prompt } }];

// The AI's message, or a plain one when the AI didn't answer.
const c = $('Config').first().json.context || {};
const ai = String(($input.first().json || {}).text || '').trim();
const tasks = (c.tasks_today || []).map((t) => '• ' + t).join('\n');
const plain = [
  'Good morning' + (c.name ? ' ' + c.name : '') + '! ☀️',
  tasks ? 'Today:\n' + tasks : 'Nothing planned today: add one small step for your goals.',
  c.streak_days ? '🔥 ' + c.streak_days + '-day streak, keep it going!' : 'Finish today\'s tasks to start a streak 🔥',
  c.link || '',
].filter(Boolean).join('\n\n');
return [{ json: { number: $('Config').first().json.number, text: (ai || plain).slice(0, 1500) } }];

const c = $input.first().json.context || {};
const prompt = [
  'Write the opening of a weekly email from Retexia Plan to ' + (c.name || 'the user') + ', in ' + (c.language || 'English') + '.',
  'Start with "Hi ' + (c.name || 'there') + '," then 3-5 sentences: the week in one line (tasks done vs planned, compared with last week), the streak, which goal did best and which needs a push, and ONE clear focus for next week. Warm and motivating, plain text, no emoji overload, no list.',
  'Use ONLY these facts, never invent numbers:',
  JSON.stringify(c, null, 1),
  'Reply with only the text.',
].join('\n');
return [{ json: { prompt } }];
